# ============================================================
# Module: acm
# Creates an ACM SSL certificate in us-east-1 (required for
# CloudFront) and auto-validates it via Route53 DNS records.
# ============================================================

# The certificate MUST live in us-east-1 for CloudFront.
# Caller must pass: providers = { aws.us_east_1 = aws.us_east_1 }
# Create certificate only when an existing_certificate_arn is NOT provided.
resource "aws_acm_certificate" "this" {
  count    = var.existing_certificate_arn == "" ? 1 : 0
  provider = aws.us_east_1

  domain_name       = var.domain_name
  validation_method = "DNS"

  subject_alternative_names = var.subject_alternative_names

  # Always create new cert before destroying old one to avoid downtime
  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name        = "broandbro-${var.environment}"
    Environment = var.environment
  }
}

# ── Fetch the Route53 hosted zone so we can write CNAME records ───────────────
# ── Fetch the Route53 hosted zone so we can write CNAME records ───────────────
data "aws_route53_zone" "this" {
  name         = var.hosted_zone_name
  private_zone = false
}

# ── Write DNS validation CNAME records to Route53 ────────────────────────────
# ── Write DNS validation CNAME records to Route53 (only when we create the cert)
resource "aws_route53_record" "validation" {

  for_each = var.existing_certificate_arn == "" ? {
    for dvo in aws_acm_certificate.this[0].domain_validation_options :
    dvo.domain_name => dvo
  } : {}

  allow_overwrite = true
  zone_id         = data.aws_route53_zone.this.zone_id

  name    = each.value.resource_record_name
  type    = each.value.resource_record_type
  ttl     = 60
  records = [each.value.resource_record_value]
}


# ── Wait for certificate to become ISSUED ────────────────────────────────────
resource "aws_acm_certificate_validation" "this" {
  count    = var.existing_certificate_arn == "" ? 1 : 0
  provider = aws.us_east_1

  certificate_arn = aws_acm_certificate.this[0].arn

  validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn]
}

# If an existing certificate ARN is provided, the module will not create
# validation records. Use the provided ARN as the module's certificate arn.

# ============================================================ # Module: acm # Creates an ACM SSL certificate in us-east-1 (required for # CloudFront) and auto-validates it via Route53 DNS records. # ============================================================
# The certificate MUST live in us-east-1 for CloudFront. # Caller must pass: providers = { aws.us_east_1 = aws.us_east_1 } # Create certificate only when an existing_certificate_arn is NOT provided. resource "aws_acm_certificate" "this" { count = var.existing_certificate_arn == "" ? 1 : 0 provider = aws.us_east_1
domain_name = var.domain_name validation_method = "DNS"
subject_alternative_names = var.subject_alternative_names
# Always create new cert before destroying old one to avoid downtime lifecycle { create_before_destroy = true }
tags = { Name = "broandbro-${var.environment}" Environment = var.environment } }
# ── Fetch the Route53 hosted zone so we can write CNAME records ─────────────── # ── Fetch the Route53 hosted zone so we can write CNAME records ─────────────── data "aws_route53_zone" "this" { name = var.hosted_zone_name private_zone = false }
# ── Write DNS validation CNAME records to Route53 ──────────────────────────── # ── Write DNS validation CNAME records to Route53 (only when we create the cert) # Use a static set of domain names for for_each to avoid plan-time unknowns resource "aws_route53_record" "validation" { for_each = var.existing_certificate_arn == "" ? toset([ for dvo in try(aws_acm_certificate.this[0].domain_validation_options, []) : dvo.domain_name ]) : toset([])
allow_overwrite = true zone_id = data.aws_route53_zone.this.zone_id
name = try( [for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.resource_record_name if dvo.domain_name == each.key][0], "" ) type = try( [for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.resource_record_type if dvo.domain_name == each.key][0], "" ) ttl = 60 records = [ try( [for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.resource_record_value if dvo.domain_name == each.key][0], "" ) ]
depends_on = [aws_acm_certificate.this] }
# ── Wait for certificate to become ISSUED ──────────────────────────────────── resource "aws_acm_certificate_validation" "this" { count = var.existing_certificate_arn == "" ? 1 : 0 provider = aws.us_east_1
certificate_arn = aws_acm_certificate.this[0].arn
validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn] }
# If an existing certificate ARN is provided, the module will not create # validation records. Use the provided ARN as the module's certificate arn.

spring: cache: type: caffeine cache-names: walletBalance,menu,menuRecommended,otp caffeine: spec: maximumSize=500,expireAfterWrite=10m,recordStats
# ── AWS Configuration ───────────────────────────────────────────────────── # Provide default region so AWS SDK doesn't fail when initializing # On EC2: EC2 instance metadata service will override this # Locally: Uses this default cloud: aws: region: static: us-east-1
# ── AWS Parameter Store Configuration ────────────────────────────────────── # Reads secrets from AWS Parameter Store (recommended for production) # Fallback: Uses environment variables if Parameter Store is not available config: import: "optional:aws-parameterstore:"
datasource: # Priority: Parameter Store → Environment Variables → Hardcoded defaults url: ${SPRING_DATASOURCE_URL:${app.parameter-store.database.url:jdbc:postgresql://broandbro-dev.chi2yu0m6hp0.us-east-1.rds.amazonaws.com:5432/broandbro_dev}} username: ${SPRING_DATASOURCE_USERNAME:${app.parameter-store.database.username:broandbro}} password: ${SPRING_DATASOURCE_PASSWORD:${app.parameter-store.database.password:BroApp#2025}}
# ── AWS Parameter Store Configuration ──────────────────────────────────────── # SSM parameter values are defined in: application-ssm-dev.yml # This file merges with application-ssm-dev.yml through Spring's profile mechanism # Do NOT add parameters here - they are imported from application-ssm-dev.yml driver-class-name: org.postgresql.Driver hikari: pool-name: ${SPRING_DATASOURCE_HIKARI_POOL_NAME:QrAppHikariPool} maximum-pool-size: ${SPRING_DATASOURCE_HIKARI_MAXIMUM_POOL_SIZE:10} minimum-idle: ${SPRING_DATASOURCE_HIKARI_MINIMUM_IDLE:2} idle-timeout: ${SPRING_DATASOURCE_HIKARI_IDLE_TIMEOUT:60000} max-lifetime: ${SPRING_DATASOURCE_HIKARI_MAX_LIFETIME:540000} connection-timeout: ${SPRING_DATASOURCE_HIKARI_CONNECTION_TIMEOUT:10000} validation-timeout: ${SPRING_DATASOURCE_HIKARI_VALIDATION_TIMEOUT:5000} keepalive-time: ${SPRING_DATASOURCE_HIKARI_KEEPALIVE_TIME:30000} connection-init-sql: "SET statement_timeout = '8s'" flyway: enabled: ${SPRING_FLYWAY_ENABLED:true} baseline-on-migrate: ${SPRING_FLYWAY_BASELINE_ON_MIGRATE:true} #repair-on-migrate: true # auto-repairs failed migration checksum on restart
jpa: hibernate: ddl-auto: validate show-sql: false open-in-view: false ## database-platform: org.hibernate.dialect.PostgreSQLDialect cors: allowed-origins: "${APP_CORS_ALLOWED_ORIGINS:https://develop.broandbro.in,http://localhost:5173}" bundle: discount-percent: 10 # 10 % of the recommended-items total max-discount-rupees: 50 # ₹50 absolute cap max-items: 3 # maximum items to include in one bundle meal: discount-percent: 10 # 10 % of the meal items total max-discount-rupees: 50 # ₹50 absolute cap
# Default profile: require explicit Razorpay credentials instead of silently using a bundled test account. razorpay: key: ${RAZORPAY_KEY:} secret: ${RAZORPAY_SECRET:} webhookSecret: ${RAZORPAY_WEBHOOK_SECRET:}
twilio: accountSid: ${TWILIO_ACCOUNT_SID:ACc9ccb1101977a6bc3adc0806c56f026f} authToken: ${TWILIO_AUTH_TOKEN:8c98ee56d052a01711546c12441b230b} fromNumber: ${TWILIO_FROM_NUMBER:whatsapp:+14155238886} orderPlacedContentSid: ${TWILIO_ORDER_PLACED_CONTENT_SID:HX7926f06db10abf2c81bd27dc98c27423} orderReadyContentSid: ${TWILIO_ORDER_READY_CONTENT_SID:} otpContentSid: ${TWILIO_OTP_CONTENT_SID:HX229f5a04fd0510ce1b071852155d3e75}
# ── AWS S3 ──────────────────────────────────────────────────────────────────── # Disabled by default for local dev — no AWS credentials needed. # To test real S3 uploads locally, export these env vars and restart: # # export AWS_S3_ENABLED=true # export AWS_ACCESS_KEY_ID=your_key # export AWS_SECRET_ACCESS_KEY=your_secret # export AWS_S3_BUCKET_NAME=qrapp-menu-images # optional, uses default # export AWS_S3_REGION=us-east-1 # optional, uses default # aws: s3: enabled: ${AWS_S3_ENABLED:true} bucket-name: ${AWS_S3_BUCKET_NAME:broandbro-menu-images-dev} region: ${AWS_S3_REGION:us-east-1} access-key: ${AWS_ACCESS_KEY_ID:AKIA34EPRSL6ICFWRYHI} secret-key: ${AWS_SECRET_ACCESS_KEY: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}
# ── Allowed CORS Origins ──────────────────────────────────────────── # Comma-separated list of frontend domains that can access the API # Override via environment variable: APP_CORS_ALLOWED_ORIGINS
# ── AWS Parameter Store Settings ──────────────────────────────────────────── # Enable auto-create only in dev environment app: parameter-store: auto-create: true # Enable auto-create in DEV environment environment: dev

